import json,numpy as np,collections
g=json.load(open('gate2.json'))
byl=collections.defaultdict(list); rows=[]
for sp,r in g.items():
    for l,dm,dt in r: byl[l].append(dm-dt); rows.append((sp,l,dm-dt))
print("residual measured - TFD, by l:")
for l in sorted(byl):
    a=np.array(byl[l]); print(f" l={l} n={len(a):2d} mean {a.mean():+.3f} rms {np.sqrt((a**2).mean()):.3f} range [{a.min():+.3f},{a.max():+.3f}]")
print("largest |residual|:"); 
for sp,l,x in sorted(rows,key=lambda t:-abs(t[2]))[:6]: print(f"  {sp} l={l} {x:+.3f}")
# neutral vs ion
neu=[x for sp,l,x in rows if sp.endswith(' I')]; ion=[x for sp,l,x in rows if not sp.endswith(' I')]
print(f"neutrals mean {np.mean(neu):+.3f} rms {np.sqrt(np.mean(np.square(neu))):.3f}; ions mean {np.mean(ion):+.3f} rms {np.sqrt(np.mean(np.square(ion))):.3f}")
EOF

